TLM.f("Sancti/02-06o",{"officium":"S. Dorothæ Virginis et Martyris","rule":["vide C6a;","Gloria"],"ruleInherited":["Gloria"],"fallback":"Commune/C6a","from":{"Introitus":"Commune/C6a","Lectio":"Commune/C6a","Graduale":"Commune/C6a","GradualeP":"Commune/C6a","Tractus":"Commune/C6a","Evangelium":"Commune/C6a","Offertorium":"Commune/C6a","Communio":"Commune/C6a"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:95-96"},{"k":"text","la":"Me exspectavérunt peccatóres, ut pérderent me: testimónia tua, Dómine, intelléxi: omnis consummatiónis vidi finem: latum mandátum tuum nimis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Me exspectavérunt peccatóres, ut pérderent me: testimónia tua, Dómine, intelléxi: omnis consummatiónis vidi finem: latum mandátum tuum nimis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Indulgéntiam nobis, quǽsumus, Dómine, beáta Dorothéa Virgo et Martyr implóret: quæ tibi grata semper éxstitit, et mérito castitátis, et tuæ professióne virtútis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 51:13-17"},{"k":"text","la":"Dómine, Deus meus, exaltásti super terram habitatiónem meam, et pro morte defluénte deprecáta sum. Invocávi Dóminum, Patrem Dómini mei, ut non derelínquat me in die tribulatiónis meæ, et in témpore superbórum sine adjutório. Laudábo nomen tuum assídue, et collaudábo illud in confessióne, et exaudíta est orátio mea. Et liberásti me de perditióne, et eripuísti me de témpore iníquo. Proptérea confitébor et laudem dicam tibi, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 45:6; 45:5"},{"k":"text","la":"Adjuvábit eam Deus vultu suo: Deus in médio ejus, non commovébitur."},{"k":"text","la":"Flúminis ímpetus lætíficat civitátem Dei: sanctificávit tabernáculum suum Altíssimus.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est Virgo sápiens, et una de número prudéntum. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est Virgo sápiens, et una de número prudéntum.","mark":"V"},{"k":"ref","la":"Sap 4:1"},{"k":"text","la":"O quam pulchra et casta generátio cum claritáte! Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 45:6; 45:5"},{"k":"text","la":"Adjuvábit eam Deus vultu suo: Deus in médio ejus, non commovébitur."},{"k":"text","la":"Flúminis ímpetus lætíficat civitátem Dei: sanctificávit tabernáculum suum Altíssimus.","mark":"V"},{"k":"text","la":"Veni, Sponsa Christi, áccipe corónam, quam tibi Dóminus præparávit in ætérnum: pro cujus amóre sánguinem tuum fudísti"},{"k":"ref","la":"Ps 44:8; 44:5"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis."},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna.","mark":"V"},{"k":"rubric","la":"Tempore paschali omittitur graduale."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 13:44-52"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile est regnum cœlórum thesáuro abscóndito in agro: quem qui invénit homo, abscóndit, et præ gáudio illíus vadit, et vendit univérsa, quæ habet, et emit agrum illum. Íterum símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas. Invénta autem una pretiósa margaríta, ábiit, et véndidit ómnia, quæ hábuit, et emit eam. Íterum símile est regnum cœlórum sagénæ missæ in mare et ex omni génere píscium congregánti. Quam, cum impléta esset, educéntes, et secus litus sedéntes, elegérunt bonos in vasa, malos autem foras misérunt. Sic erit in consummatióne sǽculi: exíbunt Angeli, et separábunt malos de médio justórum, et mittent eos in camínum ignis: ibi erit fletus et stridor déntium. Intellexístis hæc ómnia? Dicunt ei: Etiam. Ait illis: Ideo omnis scriba doctus in regno cœlórum símilis est hómini patrifamílias, qui profert de thesáuro suo nova et vétera."}],"Offertorium":[{"k":"ref","la":"Ps 44:3"},{"k":"text","la":"Diffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum, et in sǽculum sǽculi."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, beátæ Dorótheæ Vírginis et Mártyris tuæ dicátas méritis, benígnus assúme: et ad perpétuum nobis tríbue proveníre subsídium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 118:121; 118:122; 118:128"},{"k":"text","la":"Feci judícium et justítiam, Dómine, non calumniéntur mihi supérbi: ad ómnia mandáta tua dirigébar, omnem viam iniquitátis ódio hábui. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Divíni múneris largitáte satiáti, quǽsumus, Dómine, Deus noster: ut, intercedénte beáta Doróthea Vírgine et Mártyre tua, in ejus semper participatióne vivámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"5fe8269c67afbec1":{"t":"<i>Pomolimo se</i>.\nNeka nam isprosi oproštenje, molimo, Gospodine, blažena Doroteja djevica i mučenica koja ti je uvijek bila mila i zaslugom čistoće i očitovanjem tvoje jakosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, da nam izmoli oproštenje blažena I., djevica i mučenica, koja Ti je uvije-k bila mila i zaslugom svoje čistoće i javnim priznavanjem Tvoje moći. Po G. n.","knRef":"Kniewald 1942, str. 822–823 (snimka 412) (OCR)"},"a97631e0cbfa1a78":{"t":"Dobrostivo primi, Gospodine, žrtvene darove koje ti posvećujemo po zaslugama blažene Doroteje djevice tvoje i mučenice, i daj da nam budu na neprestanu pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, blagostivo žrtve, što Ti ih prinosimo zaslugama blaženoga I., Tvoga mučenika i biskupa i podaj, da nam ishode neprestanu Tvoju pomoć. Po G. n.","knRef":"Kniewald 1942, str. 804–805 (snimka 403) (OCR)"},"d9bb1e300ad06598":{"t":"<i>Pomolimo se</i>.\nNasićeni obilnim Božjim darovima, molimo, Gospodine Bože naš, da po zagovoru blažene Doroteje tvoje djevice i mučenice, uvijek živimo sudjelujući u njima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
